  "ui.wpAdminAgentFrameApp.feedback100": "لا يتوفر مشغّل CLI محلي. افتح الإعدادات ← التنفيذ واربط OpenCode أو مشغّلًا آخر مدعومًا.",
  "ui.wpAdminAgentFrameApp.feedback101": "اختر وكيلًا متاحًا في الإعدادات ← التنفيذ.",
  "ui.wpAdminAgentFrameApp.feedback102": "يُرجى إرفاق {value1} مجددًا لتحديد موقع مساحة الرفع الخاصة به.",
  "ui.wpAdminAgentFrameApp.feedback103": "هدف القراءة المحدد {value1} غير مخوّل في سياق إدارة WordPress الحالي. لم أُجرِ أي تغييرات.",
  "ui.wpAdminAgentFrameApp.feedback104": "تعذّر إعادة تفويض منشور WordPress المحدد صراحةً {value1}. لم أُجرِ أي تغييرات.",
  "ui.wpAdminAgentFrameApp.feedback105": "تعذّر تحميل مستند Gutenberg الحالي بالكامل ({value1}). لم أُجرِ أي تغييرات.",
  "ui.wpAdminAgentFrameApp.feedback106": "مستند Gutenberg الحالي متاح فقط كلقطة مرتبطة مقسّمة إلى أجزاء. لا يمكن تجهيز تعديل للمستند بأكمله حتى تُقرأ جميع الأجزاء المطلوبة. لم أُجرِ أي تغييرات.",
  "ui.wpAdminAgentFrameApp.feedback107": "يحتوي منشور Gutenberg الحالي على تغييرات غير محفوظة في المحرر. احفظه أو حدّثه قبل أن يقرأه Pixflow أو يجهّز تعديلًا يراعي محتواه. لم أُجرِ أي تغييرات.",
  "ui.wpAdminAgentFrameApp.feedback108": "مسح جميع كتل Gutenberg غير مدعوم حاليًا. لم يفسّر Pixflow الطلب كاستبدال فارغ، ولم يتغيّر شيء.",
  "ui.wpAdminAgentFrameApp.feedback109": "تعذّر على Pixflow تحديد ما إذا كانت هذه الرسالة تجيب عن الاستيضاح المعلّق أو تبدأ طلبًا جديدًا. لم تُجهّز مراجعة ولم يتغيّر شيء.",
  "ui.wpAdminAgentFrameApp.feedback110": "مستند Gutenberg الحالي مقسّم إلى أجزاء ولم يُقرأ بالكامل، لذا لا يستطيع Pixflow تجهيز مراجعة للمستند بأكمله. لم أُجرِ أي تغييرات.",
  "ui.wpAdminAgentFrameApp.feedback111": "لم يُطلب صراحةً استبدال Gutenberg بالكامل، لذا رفض Pixflow استبدال المستند الحالي. لم يتغيّر شيء.",
  "ui.wpAdminAgentFrameApp.feedback112": "تعذّر على Pixflow تحديث صلاحيات كائن WordPress بعد الإجراء السابق. سيجري التراجع عن الإجراءات السابقة.",
