  "wp.message.26a6374fbf59": "تعذّر بدء إحدى إضافات Pixflow. تحقّق من توافق إضافات Pixflow ثم أعد التحميل. قد تظل الميزات الأخرى متاحة.",
  "wp.message.ca7714cffbcc": "تفعيل Pro",
  "wp.message.197c83a2f752": "استعد أدواتك المميزة مع إضافة Pro. يبقى ترخيصك ومحتواك وإعداداتك المحفوظة كما هي. إذا كنت تستخدم المصادقة الثنائية في Bricks، فأعد تفعيلها في الإعدادات بعد تفعيل Pro.",
  "wp.message.2ffdcbc380ea": "اعمل باستخدام أداة البناء المفضلة لديك. أضف التعليقات التوضيحية والصوت وأنظمة التصميم وتوليد الصور إلى سير عملك.",
  "wp.message.40ed1102964b": "التحقّق من تجربة Pro",
  "wp.message.e9cccd3ef5fc": "تعذّر حفظ الإغلاق. يُرجى المحاولة مجددًا.",
  "wp.message.1372089fb797": "إغلاق لافتة Pixflow Pro",
  "wp.message.5e3ba715018d": "تنزيل Pro",
  "wp.message.fb2e6d87b44c": "مزيد من الإمكانات مع Pixflow Design Pro",
  "wp.message.9934717ca744": "حدّث هذه الصفحة وحاول مجددًا.",
  "wp.message.7c78f9990490": "ابدأ تجربتك المجانية لـ Pro لمدة 7 أيام",
  "wp.message.f89b4dcf2c2e": "جرّب Pro لمدة 7 أيام",
  "wp.message.69ecce9deb2d": "لا يمكنك إغلاق هذا الإشعار.",
