  "ui.mediaStarter.image1.title": "صورة شخصية تحريرية",
  "ui.mediaStarter.image1.tag": "صورة شخصية",
  "ui.mediaStarter.image1.prompt": "صورة شخصية تحريرية مقرّبة لمدير إبداعي شاب في أواخر العشرينيات، ضوء طبيعي ناعم عبر نوافذ استوديو طويلة، لوحة ألوان محايدة دافئة (كريمي وتاوب وأسود ناعم)، بعدسة 85mm عند f/1.8 وعمق ميدان ضحل، نظرة واضحة مباشرة إلى الكاميرا، حبيبات فيلم خفيفة، ومظهر دون مكياج.",
  "ui.mediaStarter.image2.title": "صورة منتج رئيسية",
  "ui.mediaStarter.image2.tag": "التجارة الإلكترونية",
  "ui.mediaStarter.image2.prompt": "لقطة منتج رئيسية راقية لكوب قهوة واحد من السيراميك المطفي على خلفية ورقية كريمية دافئة. ضوء حواف حاد من أعلى اليسار، ظل لطيف ممتد إلى أسفل اليمين، وبخار خفيف يتصاعد من الكوب. قص مربع وتكوين مركزي ومساحة أعلى الصورة للعنوان، دون إكسسوارات أو أيدٍ.",
  "ui.mediaStarter.image3.title": "رسم توضيحي مسطح",
  "ui.mediaStarter.image3.tag": "رسم توضيحي",
  "ui.mediaStarter.image3.prompt": "رسم متجهي مسطح لركن قراءة مريح بجوار نافذة ممطرة: أشكال هندسية ولوحة محدودة من خمسة ألوان (كريمي وتيراكوتا وأزرق مخضر داكن وسيينا محروقة وأسود ناعم)، خطوط رفيعة 1.5px، دون تدرجات أو خامات، وظلال ناعمة على الكرسي الأمامي فقط.",
  "ui.mediaStarter.video1.title": "الكشف عن منتج",
  "ui.mediaStarter.video1.tag": "سينمائي",
  "ui.mediaStarter.video1.prompt": "كشف عن منتج مدته 5 ثوانٍ: زجاجة عناية بالبشرة راقية وبسيطة على سطح حجري كريمي نظيف، ضوء جانبي ناعم من يسار الكاميرا، اقتراب بطيء، انتقال خفيف للتركيز من الغطاء إلى الملصق، حركة هادئة، دون نصوص أو أشخاص.",
  "ui.mediaStarter.video2.title": "فانوس عن قرب",
  "ui.mediaStarter.video2.tag": "أجواء",
  "ui.mediaStarter.video2.prompt": "لقطة سينمائية مقرّبة مدتها 6 ثوانٍ لامرأة شابة تحمل فانوسًا ورقيًا مضيئًا في غابة صنوبر ضبابية وقت الساعة الذهبية. عمق ميدان ضحل على عينيها، حركة اقتراب لطيفة، جسيمات تتطاير في شعاع دافئ، دون حوار، أصوات الغابة فقط.",
  "ui.mediaStarter.video3.title": "انجراف في شارع نيون",
  "ui.mediaStarter.video3.tag": "حركة",
  "ui.mediaStarter.video3.prompt": "لقطة تتبّع لسباق شوارع مدتها 5 ثوانٍ ليلًا في زقاق سايبربانك في هونغ كونغ مضاء بالنيون. كاميرا منخفضة تتبع سيارة رياضية سوداء مطفية تنجرف حول منعطف حاد، ضبابية حركة على العجلات، توهجات عدسة من لافتات النيون، أسفلت مبلل يعكس الأضواء، دون نص على الشاشة.",
  "ui.mediaStarter.hyperframes1.title": "كشف بعدسة مكبرة",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "أنشئ تكوينًا مدته 5 ثوانٍ بسطر واحد من نص عرض عريض على لوحة نظيفة. حرّك عدسة مكبرة دائرية من اليسار إلى اليمين فوق السطر، مع انكسار زجاجي خفيف يشوّه الحروف أسفلها أثناء مرورها. استخدم HyperFrames html-in-canvas لالتقاط DOM النص وتشغيل مؤثر العدسة فوقه بتمرير بأسلوب vfx-liquid-glass. النص بـ CSS خالص والزجاج طبقة WebGL.",
  "ui.mediaStarter.hyperframes2.title": "مشهد طرفية CRT",
  "ui.mediaStarter.hyperframes2.tag": "مؤثرات قديمة",
  "ui.mediaStarter.hyperframes2.prompt": "أنشئ تكوين شاشة CRT: لوحة داكنة ونص طرفية أحادي المسافة يكتب `npx hyperframes init my-video`، ثم يستدعي `claude` بالطلب «أضف تأثير CRT باستخدام HTML-in-canvas». طبّق مؤثر انحناء محدب خفيف وخطوط مسح وانحرافًا لونيًا بسيطًا وتوهج فوسفور ناعمًا فوق DOM الحي عبر html-in-canvas. يبقى نص الطرفية CSS حقيقيًا ليكون حادًا قبل تمرير المؤثر.",
  "ui.mediaStarter.hyperframes3.title": "تفكك رقمي",
  "ui.mediaStarter.hyperframes3.tag": "تشويش رقمي",
  "ui.mediaStarter.hyperframes3.prompt": "أنشئ تكوينًا مدته 6 ثوانٍ يعرض عنوانًا رئيسيًا وعنوانًا فرعيًا من سطر واحد على لوحة داكنة، ثم يتفكك بتشويش رقمي حاد: فصل قنوات RGB وشرائط إزاحة أفقية وتقطّع وجيز للإطارات ثم عودة نهائية نظيفة. التقط DOM الحي عبر html-in-canvas وشغّل مؤثر التشويش فوقه، ليبقى النص CSS حقيقيًا أسفل المؤثر.",
  "ui.mediaStarter.audio1.title": "تعليق صوتي للعلامة التجارية",
  "ui.mediaStarter.audio1.tag": "كلام",
  "ui.mediaStarter.audio1.prompt": "تعليق سردي دافئ مدته 30 ثانية لفيديو إطلاق منتج: واثق لكن حواري، بسرعة متوسطة، مع وقفة بعد اسم العلامة. النص: 'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' باللغة الإنجليزية وبلكنة أمريكية شمالية محايدة.",
  "ui.mediaStarter.audio2.title": "سرد ترحيبي",
  "ui.mediaStarter.audio2.tag": "كلام",
  "ui.mediaStarter.audio2.prompt": "سرد ترحيبي ودود مدته 20 ثانية لشاشة التشغيل الأول لتطبيق هاتف. نبرة مطمئنة ومبتسمة، بطيئة بما يكفي لإظهار الاهتمام دون أن تبدو مقروءة. النص: «مرحبًا بك في Loop. لنجهّز مساحتك: ثلاثة أسئلة سريعة وتصبح جاهزًا. يمكنك تغيير كل ذلك لاحقًا».",
  "ui.mediaStarter.audio3.title": "قراءة مقطع قصصي",
  "ui.mediaStarter.audio3.tag": "كلام",
  "ui.mediaStarter.audio3.prompt": "قراءة سينمائية مدتها 45 ثانية لمقطع افتتاحي. أداء منخفض ومتّزن مع أنفاس بين الجمل وإحساس حميم لميكروفون قريب. النص: «تنام المدينة على أجزاء. تومض لافتة نيون فوق منضدة الرامن. عبر الجادة، تتوهج نافذة؛ الوحيدة التي ما زالت مضاءة على هذا الجانب من منتصف الليل».",
  "ui.finalWorkspace.72ed7e2a11": "نماذج عائلات الخطوط",
  "ui.finalWorkspace.6c4afb487e": "نظام ترميز لوني لأنواع البيانات",
